CustomField.formula:
/*IF(AND(NOT(ISBLANK(Requested_Ship_Date_Change__c) ),
       YEAR(Requested_Ship_Date_Change__c) > YEAR(Customer_Requested_Date__c)
   ), 
   IF(Requested_Quantity_Change__c > 0, Requested_Quantity_Change__c* IF(Requested_Price_Change__c > 0, Requested_Price_Change__c, UnitPrice) , Total_Price__c), 
   0
)*/
IF(AND(NOT(ISBLANK(Requested_Ship_Date_Change__c) ),
       YEAR(Requested_Ship_Date_Change__c) > YEAR(Customer_Requested_Date__c)
   ), 
   IF(Requested_Quantity_Change__c > 0, 
      Requested_Quantity_Change__c*UnitPrice ,  
      Quantity*UnitPrice), 
   0
)
